// Common PolyBench-style definitions (DATA_TYPE, etc.)
#include "defines.hpp"

// Benchmark-specific definitions (N, TSTEPS, etc.)
#include "adi.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/*
 * Initialize array u:
 *
 * Original C:
 *   for (i = 0; i < n; i++)
 *     for (j = 0; j < n; j++)
 *       u[i][j] = (DATA_TYPE)(i + n - j) / n;
 *
 * C array u[i][j] is mapped to Halide Buffer u(j, i).
 *
 * Here we express the initialization as a Halide pipeline and
 * schedule it for cache-friendly, vectorized, and parallel execution.
 */
static void init_array(int n, Halide::Buffer<num_t, 2> u) {
    // x == j (fast), y == i (slow)
    Var x("x"), y("y");
    Func init_u("init_u");

    // u[i][j] = (i + n - j) / n  ==>  u(j, i) = ...
    init_u(x, y) = cast<num_t>(y + n - x) / cast<num_t>(n);

    // Choose a good vector width for this machine and element type.
    Target target = get_host_target();
    const int vec = target.natural_vector_size<num_t>();

    // Scheduling:
    // - x is contiguous in memory (Halide dim 0), so we vectorize over x.
    // - y is outer; parallelize over rows.
    init_u
        .vectorize(x, vec)
        .parallel(y);

    // Realize directly into the pre-allocated buffer 'u'.
    init_u.realize(u, target);
}

/*
 * Main computational kernel translated to C++ operating on Halide::Buffer.
 *
 * Original signature:
 *
 *   void kernel_adi(int tsteps, int n,
 *                   DATA_TYPE u[N][N],
 *                   DATA_TYPE v[N][N],
 *                   DATA_TYPE p[N][N],
 *                   DATA_TYPE q[N][N]);
 *
 * Mapping of C indices A[i][j] -> Buffer A(j, i).
 *
 * NOTE:
 * The ADI kernel is essentially a collection of 1D tridiagonal
 * solves (Thomas algorithm) along rows/columns, which have strong
 * loop-carried dependencies in the sweep direction. These
 * recurrences (e.g. p[i][j] depending on p[i][j-1]) cannot be
 * expressed as legal Halide reduction updates without changing the
 * math, so we leave the sweeps as imperative loops, but:
 *   - keep the storage layout cache-friendly,
 *   - hoist loop invariants,
 *   - and parallelize across independent lines (i dimension).
 */
static void kernel_adi(int tsteps,
                       int n,
                       Halide::Buffer<num_t, 2> u,
                       Halide::Buffer<num_t, 2> v,
                       Halide::Buffer<num_t, 2> p,
                       Halide::Buffer<num_t, 2> q) {
    // Scalar parameters (same math as original).
    const num_t DX   = num_t(1.0) / num_t(n);
    const num_t DY   = num_t(1.0) / num_t(n);
    const num_t DT   = num_t(1.0) / num_t(tsteps);
    const num_t B1   = num_t(2.0);
    const num_t B2   = num_t(1.0);
    const num_t mul1 = B1 * DT / (DX * DX);
    const num_t mul2 = B2 * DT / (DY * DY);

    const num_t one = num_t(1.0);
    const num_t two = num_t(2.0);

    const num_t a = -mul1 / two;
    const num_t b = one + mul1;
    const num_t c = a;

    const num_t d = -mul2 / two;
    const num_t e = one + mul2;
    const num_t f = d;

    // Precompute (1 + 2*d) and (1 + 2*a) used inside inner loops.
    const num_t one_plus_2d = one + two * d;
    const num_t one_plus_2a = one + two * a;

    // Time-stepping loop
    for (int t = 1; t <= tsteps; t++) {

        // ------------------------------------------------------------
        // Column sweep
        // Each i-slice is independent; we can parallelize over i.
        // Memory layout: Buffer(j, i) so j is the fast (contiguous) dim.
        // ------------------------------------------------------------
        // Optional OpenMP parallelism; if not compiled with -fopenmp,
        // this pragma is simply ignored by the compiler.
        #pragma omp parallel for schedule(static)
        for (int i = 1; i < n - 1; i++) {
            // v[0][i] = 1.0;
            v(i, 0) = one;

            // p[i][0] = 0.0;
            p(0, i) = num_t(0.0);

            // q[i][0] = v[0][i];
            // v[0][i] is 1.0, so we can write it directly.
            q(0, i) = one;

            // Forward sweep along j (Thomas forward elimination).
            for (int j = 1; j < n - 1; j++) {
                // denom = a * p[i][j-1] + b;
                const num_t p_prev = p(j - 1, i);
                const num_t denom  = a * p_prev + b;

                // p[i][j] = -c / denom;
                p(j, i) = -c / denom;

                // q[i][j] =
                //   (-d * u[j][i-1]
                //    + (1 + 2*d) * u[j][i]
                //    - f * u[j][i+1]
                //    - a * q[i][j-1]) /
                //   denom;
                const num_t u_im1 = u(i - 1, j);
                const num_t u_i   = u(i,     j);
                const num_t u_ip1 = u(i + 1, j);
                const num_t q_prev = q(j - 1, i);

                const num_t num =
                    -d * u_im1 +
                    one_plus_2d * u_i -
                    f * u_ip1 -
                    a * q_prev;

                q(j, i) = num / denom;
            }

            // v[n-1][i] = 1.0;
            v(i, n - 1) = one;

            // Back substitution along j (descending).
            for (int j = n - 2; j >= 1; j--) {
                // v[j][i] = p[i][j] * v[j+1][i] + q[i][j];
                v(i, j) = p(j, i) * v(i, j + 1) + q(j, i);
            }
        }

        // ------------------------------------------------------------
        // Row sweep
        // Again, each i-slice (row in the original C layout) is
        // independent and can be parallelized.
        // ------------------------------------------------------------
        #pragma omp parallel for schedule(static)
        for (int i = 1; i < n - 1; i++) {
            // u[i][0] = 1.0;
            u(0, i) = one;

            // p[i][0] = 0.0;
            p(0, i) = num_t(0.0);

            // q[i][0] = u[i][0];
            // u[i][0] is 1.0.
            q(0, i) = one;

            // Forward sweep along j (Thomas forward elimination).
            for (int j = 1; j < n - 1; j++) {
                // denom = d * p[i][j-1] + e;
                const num_t p_prev = p(j - 1, i);
                const num_t denom  = d * p_prev + e;

                // p[i][j] = -f / denom;
                p(j, i) = -f / denom;

                // q[i][j] =
                //   (-a * v[i-1][j]
                //    + (1 + 2*a) * v[i][j]
                //    - c * v[i+1][j]
                //    - d * q[i][j-1]) /
                //   denom;
                const num_t v_j_im1 = v(j, i - 1);
                const num_t v_j_i   = v(j, i);
                const num_t v_j_ip1 = v(j, i + 1);
                const num_t q_prev  = q(j - 1, i);

                const num_t num =
                    -a * v_j_im1 +
                    one_plus_2a * v_j_i -
                    c * v_j_ip1 -
                    d * q_prev;

                q(j, i) = num / denom;
            }

            // u[i][n-1] = 1.0;
            u(n - 1, i) = one;

            // Back substitution along j (descending).
            for (int j = n - 2; j >= 1; j--) {
                // u[i][j] = p[i][j] * u[i][j+1] + q[i][j];
                u(j, i) = p(j, i) * u(j + 1, i) + q(j, i);
            }
        }
    }
}

int main(int argc, char *argv[]) {
    // Problem sizes
    int n      = N;
    int tsteps = TSTEPS;

    // Allocate Buffers.
    // C array A[i][j] is mapped as Buffer A(j, i) with shape (n, n).
    Halide::Buffer<num_t, 2> u(n, n);
    Halide::Buffer<num_t, 2> v(n, n);
    Halide::Buffer<num_t, 2> p(n, n);
    Halide::Buffer<num_t, 2> q(n, n);

    // Initialize u; v, p, q are scratch arrays.
    init_array(n, u);

    // Time only the kernel.
    auto start = std::chrono::high_resolution_clock::now();

    kernel_adi(tsteps, n, u, v, p, q);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally dump the result (u) to stderr, in row-major order.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // u[i][j] == u_buf(j, i)
                std::cerr << u(j, i) << '\n';
            }
        }
    }

    // Print timing (seconds) to stdout.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
