static void init_array(int n, Halide::Buffer<num_t, 2> u) {
    // x == j (fast), y == i (slow)
    Var x("x"), y("y");
    Func init_u("init_u");

    // Build the expression using Halide Exprs to avoid implicit type surprises.
    Expr n_expr    = cast<num_t>(Expr(n));
    Expr numerator = cast<num_t>(y + Expr(n) - x);

    // u[i][j] = (i + n - j) / n  ==>  u(j, i) = ...
    init_u(x, y) = numerator / n_expr;

    // Simple CPU schedule:
    //  - vectorize along x (j) for good use of SIMD
    //  - parallelize along y (i) to use multiple cores
    const int vec_width = 8;  // Reasonable default for modern x86; safe on other CPUs.
    init_u
        .vectorize(x, vec_width)
        .parallel(y);

    // JIT-compile and realize into the provided buffer.
    init_u.realize(u);
}

/*
 * Main computational kernel translated to C++ operating on Halide::Buffer.
 *
 * Original signature:
 *
 *   void kernel_adi(int tsteps, int n,
 *                   DATA_TYPE u[N][N],
 *                   DATA_TYPE v[N][N],
 *                   DATA_TYPE p[N][N],
 *                   DATA_TYPE q[N][N]);
 *
 * Mapping of C indices A[i][j] -> Buffer A(j, i).
 *
 * This routine keeps the original Thomas-ADI algorithm (with its
 * inherent sequential recurrences along j) in C++, but applies some
 * algebraic optimizations:
 *   - Hoists common constants out of the loops.
 *   - Reduces the number of floating-point divisions by sharing the
 *     inverse of the denominator between p and q updates.
 *   - Reuses precomputed combinations such as (1 + 2*d) and (1 + 2*a).
 *
 * The data layout (Buffer(j, i)) and loop ordering (i outer, j inner)
 * preserve good spatial locality: inner loops traverse the contiguous
 * x-dimension of the Halide::Buffer.
 */
static void kernel_adi(int tsteps,
                       int n,
                       Halide::Buffer<num_t, 2> u,
                       Halide::Buffer<num_t, 2> v,
                       Halide::Buffer<num_t, 2> p,
                       Halide::Buffer<num_t, 2> q) {
    // Frequently used scalar constants.
    const num_t one = num_t(1.0);
    const num_t two = num_t(2.0);

    // Discretization parameters.
    const num_t DX = one / num_t(n);
    const num_t DY = one / num_t(n);
    const num_t DT = one / num_t(tsteps);

    const num_t B1 = num_t(2.0);
    const num_t B2 = num_t(1.0);

    const num_t mul1 = B1 * DT / (DX * DX);
    const num_t mul2 = B2 * DT / (DY * DY);

    // Coefficients for the implicit solves.
    const num_t a = -mul1 / two;
    const num_t b = one + mul1;
    const num_t c = a;

    const num_t d = -mul2 / two;
    const num_t e = one + mul2;
    const num_t f = d;

    // Precompute combinations and signs used inside the inner loops.
    const num_t minus_c     = -c;
    const num_t minus_f     = -f;
    const num_t one_plus_2d = one + two * d;
    const num_t one_plus_2a = one + two * a;

    // Time-stepping loop (sequential by construction).
    for (int t = 1; t <= tsteps; t++) {

        // ------------------------------------------------------------
        // Column sweep (implicit in y, solving tri-diagonals along j).
        // Each i-column is independent and iterated serially here;
        // inner loop over j walks the contiguous x-dimension.
        // ------------------------------------------------------------
        for (int i = 1; i < n - 1; i++) {
            // v[0][i] = 1.0;
            v(i, 0) = one;

            // p[i][0] = 0.0;
            p(0, i) = num_t(0.0);

            // q[i][0] = v[0][i];
            q(0, i) = v(i, 0);

            // Forward sweep along j (Thomas algorithm).
            for (int j = 1; j < n - 1; j++) {
                // denom = a * p[i][j-1] + b;
                const num_t denom     = a * p(j - 1, i) + b;
                const num_t inv_denom = one / denom;  // share this between p and q

                // p[i][j] = -c / denom;
                p(j, i) = minus_c * inv_denom;

                // q[i][j] =
                //   (-d * u[j][i-1]
                //    + (1 + 2*d) * u[j][i]
                //    - f * u[j][i+1]
                //    - a * q[i][j-1]) / denom;
                const num_t num =
                    -d * u(i - 1, j) +
                    one_plus_2d * u(i, j) -
                    f * u(i + 1, j) -
                    a * q(j - 1, i);

                q(j, i) = num * inv_denom;
            }

            // v[n-1][i] = 1.0;
            v(i, n - 1) = one;

            // Back substitution along j (descending).
            for (int j = n - 2; j >= 1; j--) {
                // v[j][i] = p[i][j] * v[j+1][i] + q[i][j];
                v(i, j) = p(j, i) * v(i, j + 1) + q(j, i);
            }
        }

        // ------------------------------------------------------------
        // Row sweep (implicit in x, solving tri-diagonals along j).
        // Again, each i-row is independent; inner loop over j
        // traverses contiguous memory in x.
        // ------------------------------------------------------------
        for (int i = 1; i < n - 1; i++) {
            // u[i][0] = 1.0;
            u(0, i) = one;

            // p[i][0] = 0.0;
            p(0, i) = num_t(0.0);

            // q[i][0] = u[i][0];
            q(0, i) = u(0, i);

            // Forward sweep along j.
            for (int j = 1; j < n - 1; j++) {
                // denom = d * p[i][j-1] + e;
                const num_t denom     = d * p(j - 1, i) + e;
                const num_t inv_denom = one / denom;  // shared

                // p[i][j] = -f / denom;
                p(j, i) = minus_f * inv_denom;

                // q[i][j] =
                //   (-a * v[i-1][j]
                //    + (1 + 2*a) * v[i][j]
                //    - c * v[i+1][j]
                //    - d * q[i][j-1]) / denom;
                const num_t num =
                    -a * v(j, i - 1) +
                    one_plus_2a * v(j, i) -
                    c * v(j, i + 1) -
                    d * q(j - 1, i);

                q(j, i) = num * inv_denom;
            }

            // u[i][n-1] = 1.0;
            u(n - 1, i) = one;

            // Back substitution along j (descending).
            for (int j = n - 2; j >= 1; j--) {
                // u[i][j] = p[i][j] * u[i][j+1] + q[i][j];
                u(j, i) = p(j, i) * u(j + 1, i) + q(j, i);
            }
        }
    }
