#include <chrono>
#include <iomanip>
#include <iostream>

#include "Halide.h"

// Common PolyBench-style definitions (DATA_TYPE, etc.)
#include "defines.hpp"

// Benchmark-specific definitions (N, TSTEPS, etc.)
#include "adi.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/*
 * Initialize array u:
 *
 * Original C:
 *   for (i = 0; i < n; i++)
 *     for (j = 0; j < n; j++)
 *       u[i][j] = (DATA_TYPE)(i + n - j) / n;
 *
 * Mapping: C array u[i][j] is mapped to Halide Buffer u(j, i).
 *
 * Here we implement the initialization as a Halide pipeline and
 * schedule it for parallel, vectorized execution over the 2D domain.
 */
static void init_array(int n, Halide::Buffer<num_t, 2> u) {
    Var x("x"), y("y"); // x == j (fast), y == i (slow)
    Func init_u("init_u");

    // Expr-typed constants to avoid implicit C++ -> Expr confusion.
    Expr n_expr = cast<num_t>(Expr(n));

    // u[i][j] = (i + n - j) / n  ==>  u(j, i) = ...
    init_u(x, y) = cast<num_t>(y + n - x) / n_expr;

    // Simple, cache-friendly schedule: vectorize across x (contiguous),
    // parallelize across y (rows).
    Target target = get_host_target();
    int vec = target.natural_vector_size(type_of<num_t>());
    if (vec < 1) vec = 1;

    init_u
        .compute_root()
        .parallel(y)
        .vectorize(x, vec);

    init_u.realize(u);
}

/*
 * Main computational kernel translated to C++ operating on Halide::Buffer.
 *
 * Original signature:
 *
 *   void kernel_adi(int tsteps, int n,
 *                   DATA_TYPE u[N][N],
 *                   DATA_TYPE v[N][N],
 *                   DATA_TYPE p[N][N],
 *                   DATA_TYPE q[N][N]);
 *
 * Mapping of C indices A[i][j] -> Buffer A(j, i).
 *
 * The ADI algorithm consists of:
 *   - A column sweep (solving many 1D tridiagonal systems in one direction)
 *   - A row sweep   (solving many 1D tridiagonal systems in the orthogonal direction)
 *
 * Each 1D tridiagonal solve is inherently sequential along that 1D line,
 * so we keep the recurrences (Thomas algorithm) as C++ for-loops,
 * but *factor out* the purely local stencil parts into Halide pipelines,
 * which are vectorized and parallelized over the 2D grid.
 *
 * This improves cache behavior and takes advantage of SIMD for the
 * finite-difference parts without violating Halide's restriction
 * against self-referential index shifts in Func definitions.
 */
static void kernel_adi(int tsteps,
                       int n,
                       Halide::Buffer<num_t, 2> u,
                       Halide::Buffer<num_t, 2> v,
                       Halide::Buffer<num_t, 2> p,
                       Halide::Buffer<num_t, 2> q) {
    // ------------------------------------------------------------------
    // Scalar coefficients (same as original C kernel)
    // ------------------------------------------------------------------
    num_t DX   = num_t(1.0) / num_t(n);
    num_t DY   = num_t(1.0) / num_t(n);
    num_t DT   = num_t(1.0) / num_t(tsteps);
    num_t B1   = num_t(2.0);
    num_t B2   = num_t(1.0);
    num_t mul1 = B1 * DT / (DX * DX);
    num_t mul2 = B2 * DT / (DY * DY);

    num_t a = -mul1 / num_t(2.0);
    num_t b = num_t(1.0) + mul1;
    num_t c = a;
    num_t d = -mul2 / num_t(2.0);
    num_t e = num_t(1.0) + mul2;
    num_t f = d;

    // ------------------------------------------------------------------
    // Halide pipelines for the *local* stencil parts
    //
    // Column sweep:
    //   q[i][j] uses
    //     -d * u[j][i-1] + (1 + 2*d) * u[j][i] - f * u[j][i+1]
    //
    // Row sweep:
    //   q[i][j] uses
    //     -a * v[i-1][j] + (1 + 2*a) * v[i][j] - c * v[i+1][j]
    //
    // In Buffer coordinates (x,y) with mapping C A[i][j] -> Buffer A(j,i),
    // the existing C++ code does:
    //
    //   // column sweep term:
    //   -d * u(i-1, j) + (1 + 2*d) * u(i, j) - f * u(i+1, j);
    //
    //   // row sweep term:
    //   -a * v(j, i-1) + (1 + 2*a) * v(j, i) - c * v(j, i+1);
    //
    // We precompute these with Halide Funcs col_rhs(j,i) and row_rhs(j,i).
    // ------------------------------------------------------------------
    Var jv("j"), iv("i");

    // ImageParams so we can re-use the same pipelines across time steps.
    ImageParam u_in(type_of<num_t>(), 2, "u_in");
    ImageParam v_in(type_of<num_t>(), 2, "v_in");

    // Boundary-condition wrappers to keep Halide's bounds analysis happy,
    // and to safely evaluate at shifted indices near the borders even
    // though we only *use* interior points (1..n-2).
    Func u_bc("u_bc"), v_bc("v_bc");
    u_bc = Halide::BoundaryConditions::repeat_edge(u_in);
    v_bc = Halide::BoundaryConditions::repeat_edge(v_in);

    // Expr-typed coefficients for use in Halide expressions.
    Expr one = cast<num_t>(Expr(1.0));
    Expr two = cast<num_t>(Expr(2.0));
    Expr d_expr = Expr(d);
    Expr f_expr = Expr(f);
    Expr a_expr = Expr(a);
    Expr c_expr = Expr(c);

    // col_rhs(j,i) = -d * u(i-1, j) + (1 + 2*d) * u(i, j) - f * u(i+1, j)
    Func col_rhs("col_rhs");
    col_rhs(jv, iv) =
        -d_expr * u_bc(iv - 1, jv) +
        (one + two * d_expr) * u_bc(iv, jv) -
        f_expr * u_bc(iv + 1, jv);

    // row_rhs(j,i) = -a * v(j, i-1) + (1 + 2*a) * v(j, i) - c * v(j, i+1)
    Func row_rhs("row_rhs");
    row_rhs(jv, iv) =
        -a_expr * v_bc(jv, iv - 1) +
        (one + two * a_expr) * v_bc(jv, iv) -
        c_expr * v_bc(jv, iv + 1);

    // Schedule these stencil computations for good locality:
    //  - compute_root(): realize once per call
    //  - parallel over iv (slow dimension)
    //  - vectorize over jv (fast dimension)
    Target target = get_host_target();
    int vec = target.natural_vector_size(type_of<num_t>());
    if (vec < 1) vec = 1;

    col_rhs
        .compute_root()
        .parallel(iv)
        .vectorize(jv, vec);

    row_rhs
        .compute_root()
        .parallel(iv)
        .vectorize(jv, vec);

    // Temporary buffers for the right-hand-side terms.
    // Size n x n is simple; we only *use* them in the interior (1..n-2).
    Halide::Buffer<num_t, 2> rhs_col(n, n);
    Halide::Buffer<num_t, 2> rhs_row(n, n);

    // ------------------------------------------------------------------
    // Time-stepping loop: keep the 1D tridiagonal solves as explicit
    // C++ loops (per PolyBench reference), but feed them with precomputed
    // Halide stencils to improve arithmetic locality and avoid repeating
    // the same 3-point operations inside the recurrences.
    // ------------------------------------------------------------------
    for (int t = 1; t <= tsteps; t++) {

        // ==========================
        // Column sweep
        // ==========================

        // Precompute the local 3-point combination in the i-direction
        // using the current u as input:
        u_in.set(u);
        col_rhs.realize(rhs_col);

        for (int i = 1; i < n - 1; i++) {
            // v[0][i] = 1.0;   --> v(i, 0)
            v(i, 0) = num_t(1.0);

            // p[i][0] = 0.0;   --> p(0, i)
            p(0, i) = num_t(0.0);

            // q[i][0] = v[0][i];  --> q(0, i) = v(i, 0)
            q(0, i) = v(i, 0);

            // Forward sweep along j (Thomas algorithm forward pass)
            for (int j = 1; j < n - 1; j++) {
                // denom = a * p[i][j-1] + b;
                num_t denom = a * p(j - 1, i) + b;

                // p[i][j] = -c / denom;
                p(j, i) = -c / denom;

                // Original:
                //   q[i][j] =
                //     (-d * u[j][i-1]
                //      + (1 + 2*d) * u[j][i]
                //      - f * u[j][i+1]
                //      - a * q[i][j-1]) / denom;
                //
                // Our factorization:
                //   rhs_col(j,i) = -d * u(i-1, j) + (1+2*d)*u(i,j) - f*u(i+1,j);
                //   q[i][j] = (rhs_col(j,i) - a * q[i][j-1]) / denom;
                num_t num = rhs_col(j, i) - a * q(j - 1, i);
                q(j, i) = num / denom;
            }

            // v[n-1][i] = 1.0;  --> v(i, n-1)
            v(i, n - 1) = num_t(1.0);

            // Back substitution along j (descending)
            for (int j = n - 2; j >= 1; j--) {
                // v[j][i] = p[i][j] * v[j+1][i] + q[i][j];
                v(i, j) = p(j, i) * v(i, j + 1) + q(j, i);
            }
        }

        // ==========================
        // Row sweep
        // ==========================

        // Precompute the local 3-point combination in the i-direction
        // (now using v as input) for the second half-step:
        v_in.set(v);
        row_rhs.realize(rhs_row);

        for (int i = 1; i < n - 1; i++) {
            // u[i][0] = 1.0;   --> u(0, i)
            u(0, i) = num_t(1.0);

            // p[i][0] = 0.0;   --> p(0, i)
            p(0, i) = num_t(0.0);

            // q[i][0] = u[i][0];  --> q(0, i) = u(0, i)
            q(0, i) = u(0, i);

            // Forward sweep along j
            for (int j = 1; j < n - 1; j++) {
                // denom = d * p[i][j-1] + e;
                num_t denom = d * p(j - 1, i) + e;

                // p[i][j] = -f / denom;
                p(j, i) = -f / denom;

                // Original:
                //   q[i][j] =
                //     (-a * v[i-1][j]
                //      + (1 + 2*a) * v[i][j]
                //      - c * v[i+1][j]
                //      - d * q[i][j-1]) /
                //     (d * p[i][j-1] + e);
                //
                // Our factorization:
                //   rhs_row(j,i) = -a*v(j, i-1) + (1+2*a)*v(j,i) - c*v(j,i+1);
                //   q[i][j] = (rhs_row(j,i) - d*q[i][j-1]) / denom;
                num_t num = rhs_row(j, i) - d * q(j - 1, i);
                q(j, i) = num / denom;
            }

            // u[i][n-1] = 1.0;  --> u(n-1, i)
            u(n - 1, i) = num_t(1.0);

            // Back substitution along j (descending)
            for (int j = n - 2; j >= 1; j--) {
                // u[i][j] = p[i][j] * u[i][j+1] + q[i][j];
                u(j, i) = p(j, i) * u(j + 1, i) + q(j, i);
            }
        }
    }
}

int main(int argc, char *argv[]) {
    // Problem sizes
    int n      = N;
    int tsteps = TSTEPS;

    // Allocate Buffers.
    // C array A[i][j] is mapped as Buffer A(j, i) with shape (n, n).
    Halide::Buffer<num_t, 2> u(n, n);
    Halide::Buffer<num_t, 2> v(n, n);
    Halide::Buffer<num_t, 2> p(n, n);
    Halide::Buffer<num_t, 2> q(n, n);

    // Initialize u; v, p, q are scratch arrays.
    init_array(n, u);

    // Time only the kernel.
    auto start = std::chrono::high_resolution_clock::now();

    kernel_adi(tsteps, n, u, v, p, q);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally dump the result (u) to stderr, in row-major order.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // C u[i][j] == Buffer u(j, i)
                std::cerr << u(j, i) << '\n';
            }
        }
    }

    // Print timing (seconds) to stdout.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
