/*
 * Main computational kernel translated to C++ operating on Halide::Buffer.
 *
 * Original signature:
 *
 *   void kernel_adi(int tsteps, int n,
 *                   DATA_TYPE u[N][N],
 *                   DATA_TYPE v[N][N],
 *                   DATA_TYPE p[N][N],
 *                   DATA_TYPE q[N][N]);
 *
 * Mapping of C indices A[i][j] -> Buffer A(j, i).
 *
 * NOTE:
 * The ADI kernel uses tridiagonal solves with strong loop-carried
 * dependencies along one spatial dimension. These are not directly
 * expressible as pure Halide Func update definitions (they would
 * require self-references at shifted coordinates, which Halide
 * forbids), so we keep the core recurrences as explicit C++ loops.
 *
 * The code below preserves the original semantics but improves
 * efficiency by:
 *   - Hoisting common subexpressions and constants.
 *   - Reusing register-resident values for the forward / backward
 *     sweeps instead of repeatedly loading p[i][j-1], q[i][j-1],
 *     v[j+1][i], u[i][j+1] from memory.
 *   - Keeping the memory layout (Halide::Buffer) and index mapping
 *     unchanged so the rest of the program remains correct.
 */
static void kernel_adi(int tsteps,
                       int n,
                       Halide::Buffer<num_t, 2> u,
                       Halide::Buffer<num_t, 2> v,
                       Halide::Buffer<num_t, 2> p,
                       Halide::Buffer<num_t, 2> q) {
    const num_t one  = num_t(1.0);
    const num_t two  = num_t(2.0);
    const num_t zero = num_t(0.0);

    // Scalar parameters (unchanged algebraically from original code)
    const num_t DX   = one / num_t(n);
    const num_t DY   = one / num_t(n);
    const num_t DT   = one / num_t(tsteps);
    const num_t B1   = num_t(2.0);
    const num_t B2   = num_t(1.0);
    const num_t mul1 = B1 * DT / (DX * DX);
    const num_t mul2 = B2 * DT / (DY * DY);

    const num_t a = -mul1 / num_t(2.0);
    const num_t b = one + mul1;
    const num_t c = a;
    const num_t d = -mul2 / num_t(2.0);
    const num_t e = one + mul2;
    const num_t f = d;

    // Frequently used constants
    const num_t one_plus_2d = one + two * d;
    const num_t one_plus_2a = one + two * a;

    // Time-stepping loop
    for (int t = 1; t <= tsteps; t++) {

        // ------------------------------------------------------------
        // Column sweep
        // ------------------------------------------------------------
        // Each iteration over i is independent (u is read-only here),
        // so a higher-level parallelization (e.g., OpenMP) could be
        // safely added if desired. We keep plain C++ here to avoid
        // extra toolchain requirements.
        for (int i = 1; i < n - 1; i++) {
            // Boundary conditions:
            //   v[0][i] = 1.0;
            //   p[i][0] = 0.0;
            //   q[i][0] = v[0][i];
            v(i, 0) = one;
            p(0, i) = zero;

            // Keep p[i][j-1] and q[i][j-1] in registers.
            num_t p_prev = zero;  // p[i][0]
            num_t q_prev = one;   // q[i][0] = v[0][i] = 1
            q(0, i) = q_prev;

            // Forward sweep along j:
            //   p[i][j] = -c / (a * p[i][j-1] + b);
            //   q[i][j] = num / denom;
            for (int j = 1; j < n - 1; j++) {
                const num_t denom = a * p_prev + b;
                const num_t p_val = -c / denom;
                p(j, i) = p_val;

                //   num =
                //     -d * u[j][i-1]
                //     + (1 + 2*d) * u[j][i]
                //     - f * u[j][i+1]
                //     - a * q[i][j-1];
                const num_t num =
                    -d * u(i - 1, j) +
                    one_plus_2d * u(i, j) -
                    f * u(i + 1, j) -
                    a * q_prev;

                const num_t q_val = num / denom;
                q(j, i) = q_val;

                // Advance recurrence state in registers.
                p_prev = p_val;
                q_prev = q_val;
            }

            // v[n-1][i] = 1.0;
            v(i, n - 1) = one;

            // Back substitution along j (descending):
            //   v[j][i] = p[i][j] * v[j+1][i] + q[i][j];
            num_t v_next = v(i, n - 1);  // v[j+1][i], starting from j = n-2

            for (int j = n - 2; j >= 1; j--) {
                const num_t v_val = p(j, i) * v_next + q(j, i);
                v(i, j) = v_val;
                v_next  = v_val;  // becomes v[j][i] for the next iteration
            }
        }

        // ------------------------------------------------------------
        // Row sweep
        // ------------------------------------------------------------
        for (int i = 1; i < n - 1; i++) {
            // Boundary conditions:
            //   u[i][0] = 1.0;
            //   p[i][0] = 0.0;
            //   q[i][0] = u[i][0];
            u(0, i) = one;
            p(0, i) = zero;

            num_t p_prev = zero;  // p[i][0]
            num_t q_prev = one;   // q[i][0] = u[i][0] = 1
            q(0, i) = q_prev;

            // Forward sweep along j:
            //   p[i][j] = -f / (d * p[i][j-1] + e);
            //   q[i][j] = num / denom;
            for (int j = 1; j < n - 1; j++) {
                const num_t denom = d * p_prev + e;
                const num_t p_val = -f / denom;
                p(j, i) = p_val;

                //   num =
                //     -a * v[i-1][j]
                //     + (1 + 2*a) * v[i][j]
                //     - c * v[i+1][j]
                //     - d * q[i][j-1];
                const num_t num =
                    -a * v(j, i - 1) +
                    one_plus_2a * v(j, i) -
                    c * v(j, i + 1) -
                    d * q_prev;

                const num_t q_val = num / denom;
                q(j, i) = q_val;

                p_prev = p_val;
                q_prev = q_val;
            }

            // u[i][n-1] = 1.0;
            u(n - 1, i) = one;

            // Back substitution along j (descending):
            //   u[i][j] = p[i][j] * u[i][j+1] + q[i][j];
            num_t u_next = u(n - 1, i);  // u[i][j+1], starting from j = n-2

            for (int j = n - 2; j >= 1; j--) {
                const num_t u_val = p(j, i) * u_next + q(j, i);
                u(j, i) = u_val;
                u_next  = u_val;  // becomes u[i][j] for the next iteration
            }
        }
    }
}

