 *  - hoists and precomputes scalar constants
 *  - reduces divisions by computing 1 / denom once and using multiplies
 *  - adds OpenMP parallel-for over the i-loop (columns / rows), which are independent
 *    between different i; if compiled without -fopenmp, the pragmas are ignored by the compiler.
 */
static void kernel_adi(int tsteps,
                       int n,
                       Halide::Buffer<num_t, 2> u,
                       Halide::Buffer<num_t, 2> v,
                       Halide::Buffer<num_t, 2> p,
                       Halide::Buffer<num_t, 2> q) {
