    const num_t DY2  = DY * DY;
    const num_t mul1 = B1 * DT / DX2;
    const num_t mul2 = B2 * DT / DY2;

    const num_t a = -mul1 / two;
    const num_t b = one + mul1;
    const num_t c = a;
    const num_t d = -mul2 / two;
    const num_t e = one + mul2;
    const num_t f = d;

    // Frequently used combinations
    const num_t one_plus_2d = one + two * d;
    const num_t one_plus_2a = one + two * a;
    const num_t neg_c       = -c;
    const num_t neg_f       = -f;

    const int n_minus_1 = n - 1;
    const int n_minus_2 = n - 2;

    // -------------------------------------------------------------------------
    // Time-stepping loop
    // -------------------------------------------------------------------------
