        // ---------------------------------------------------------------------
        // Column sweep
        //   Loops over i are independent, so we can parallelize them.
        //   Dependencies are only along j within a single (fixed) i.
        // ---------------------------------------------------------------------
#pragma omp parallel for schedule(static)
        for (int i = 1; i < n_minus_1; i++) {
            // v[0][i] = 1.0;
            v(i, 0) = one;

            // p[i][0] = 0.0;
            p(0, i) = zero;

            // q[i][0] = v[0][i];
            q(0, i) = v(i, 0);

            // Forward sweep along j (1 .. n-2)
            for (int j = 1; j < n_minus_1; j++) {
