                const num_t u_j_im1 = u(i - 1, j);
                const num_t u_j_i   = u(i,     j);
                const num_t u_j_ip1 = u(i + 1, j);
                const num_t q_prev  = q(j - 1, i);

                const num_t num =
                    -d * u_j_im1 +
                    one_plus_2d * u_j_i +
                    neg_f * u_j_ip1 -
                    a * q_prev;

                q(j, i) = num * inv_denom;
            }

            // v[n-1][i] = 1.0;
            v(i, n_minus_1) = one;

            // Back substitution along j (descending: n-2 .. 1)
            for (int j = n_minus_2; j >= 1; j--) {
                // v[j][i] = p[i][j] * v[j+1][i] + q[i][j];
